#!/usr/bin/env bash
# Build the pinned libimobiledevice stack into vendor/prefix.
# Does not touch system library paths or package-manager copies.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
LOCK="${ROOT}/vendor/versions.lock"
SRC_ROOT="${EASYRESTORE_VENDOR_SRC:-${ROOT}/vendor/src}"
PREFIX="${EASYRESTORE_VENDOR_PREFIX:-${ROOT}/vendor/prefix}"
JOBS="${EASYRESTORE_BUILD_JOBS:-$(nproc 2>/dev/null || echo 4)}"

log() { printf '==> %s\n' "$*"; }
die() { printf 'error: %s\n' "$*" >&2; exit 1; }

need_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "missing build tool: $1"
}

for cmd in git python3 autoconf automake libtool pkg-config make gcc; do
  need_cmd "$cmd"
done

mapfile -t COMPONENTS < <(python3 - "$LOCK" <<'PY'
import sys
import tomllib

with open(sys.argv[1], "rb") as fh:
    data = tomllib.load(fh)

for comp in data["components"]:
    extras = "\x1f".join(comp.get("extra_configure", []))
    print(
        "\t".join(
            [
                comp["name"],
                comp["commit"],
                comp["url"],
                extras,
            ]
        )
    )
PY
)

mkdir -p "${SRC_ROOT}" "${PREFIX}" "${PREFIX}/lib/udev/rules.d"

export PKG_CONFIG_PATH="${PREFIX}/lib/pkgconfig:${PREFIX}/lib64/pkgconfig${PKG_CONFIG_PATH:+:${PKG_CONFIG_PATH}}"
export LD_LIBRARY_PATH="${PREFIX}/lib:${PREFIX}/lib64${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}"
export PATH="${PREFIX}/bin:${PATH}"
export ACLOCAL_PATH="${PREFIX}/share/aclocal${ACLOCAL_PATH:+:${ACLOCAL_PATH}}"
export CFLAGS="${CFLAGS:--O2 -g}"
export CXXFLAGS="${CXXFLAGS:-${CFLAGS}}"

checkout() {
  local name="$1" commit="$2" url="$3"
  local dest="${SRC_ROOT}/${name}"
  if [[ ! -d "${dest}/.git" ]]; then
    log "cloning ${name}"
    git clone --quiet "${url}" "${dest}"
  else
    log "fetching ${name}"
    git -C "${dest}" fetch --quiet --tags origin
  fi
  git -C "${dest}" checkout --quiet --detach "${commit}"
  local got
  got="$(git -C "${dest}" rev-parse HEAD)"
  [[ "${got}" == "${commit}" ]] || die "${name}: expected ${commit}, got ${got}"
}

configure_extras_for() {
  # Keep udev rules inside the vendor prefix — never write to /usr during build.
  case "$1" in
    libirecovery|usbmuxd)
      printf '%s\n' "--with-udevrulesdir=${PREFIX}/lib/udev/rules.d"
      ;;
  esac
}

build_autotools() {
  local name="$1"
  shift
  local dest="${SRC_ROOT}/${name}"
  log "building ${name}"
  pushd "${dest}" >/dev/null
  if [[ -x ./autogen.sh ]]; then
    NOCONFIGURE=1 ./autogen.sh
  elif [[ -x ./configure ]]; then
    :
  else
    die "${name}: no autogen.sh or configure"
  fi
  ./configure --prefix="${PREFIX}" --enable-shared "$@"
  make -j"${JOBS}"
  make install
  popd >/dev/null
}

for row in "${COMPONENTS[@]}"; do
  IFS=$'\t' read -r name commit url extras <<<"${row}"
  checkout "${name}" "${commit}" "${url}"
  extra_args=()
  if [[ -n "${extras}" ]]; then
    IFS=$'\x1f' read -r -a extra_args <<<"${extras}"
  fi
  mapfile -t udev_args < <(configure_extras_for "${name}")
  build_autotools "${name}" ${udev_args[@]+"${udev_args[@]}"} ${extra_args[@]+"${extra_args[@]}"}
done

cat > "${ROOT}/vendor/env.sh" <<EOF
# Generated by vendor/build.sh — source this before running bundled tools.
export EASYRESTORE_VENDOR_PREFIX="${PREFIX}"
export PATH="${PREFIX}/bin:${PREFIX}/sbin:\$PATH"
export LD_LIBRARY_PATH="${PREFIX}/lib:${PREFIX}/lib64\${LD_LIBRARY_PATH:+:\$LD_LIBRARY_PATH}"
export PKG_CONFIG_PATH="${PREFIX}/lib/pkgconfig:${PREFIX}/lib64/pkgconfig\${PKG_CONFIG_PATH:+:\$PKG_CONFIG_PATH}"
EOF

log "vendored stack installed to ${PREFIX}"
log "source vendor/env.sh to use the bundled binaries"
